INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "1元=（　）角＝（　）分", "options": null}', '10角；100分', '1元=10角；1角=10分，所以1元=100分。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p013.png"]');
