INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "在○里填上“＞”“＜”或“＝”：38角○60分", "options": null}', '＞', '38角=380分，380分＞60分（38角=3元8角，远大于6角）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p014.png"]');
