INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "小海要买一个58元的书包，如果只用10元的人民币付款，那么要付（　）张。", "options": null}', '6张', '5张10元只有50元，不够付58元；6张10元是60元，够付还能找回2元，所以至少要付6张。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p014.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "妈妈用一张50元的人民币买一个玩具，找回6元，这个玩具的价格是（　）。", "options": ["A.40元", "B.44元", "C.46元"]}', 'B', '找回6元，说明玩具价格=50-6=44（元）；40元应找回10元、46元应找回4元，均与“找回6元”不符。选B。（卷面币图为纸币，由其值50元唯一可确定）', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p014.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem": "乐乐买了一个书包，付了3张20元的人民币，找回的钱比5元多、比10元少。书包的价格可能是（　）。", "options": ["A.55元", "B.53元", "C.50元"]}', 'B', '3张20元共60元。若买55元找回5元，不满足“比5元多”；若买50元找回10元，不满足“比10元少”；若买53元找回7元，5＜7＜10，符合。选B。（卷面为3张同面值纸币图，由选项唯一反推面值20元）', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p014.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 2, '{"stem": "小红买一本16元的故事书，她付了两张8元的人民币。（　）", "options": null}', '×', '人民币没有8元面值的纸币（常见面值有1元、5元、10元、20元、50元、100元等），付两张8元人民币不成立。说法错误。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem": "5张10元的钱和10张5元的钱同样多。（　）", "options": null}', '√', '5张10元是50元，10张5元也是50元，同样多。说法正确。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem": "妈妈买白菜用去3元，买萝卜用去9元，一共花了12角。（　）", "options": null}', '×', '3元+9元=12元，不是12角（12角=1元2角）。说法错误。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "9角-4角=（　）角", "options": null}', '5角', '9角-4角=5角。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
