INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "2元7角-7角=（　）元", "options": null}', '2元', '2元7角去掉7角，还剩整的2元。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "6元+8元=（　）元", "options": null}', '14元', '6+8=14，所以是14元。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem": "3角+4元2角=（　）元（　）角", "options": null}', '4元5角', '4元2角加3角，角相加：2角+3角=5角，共4元5角。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p015.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "欢欢要买两种不同的玩具，至少要花（　）元。", "options": null}', '9元', '四种玩具的价格分别是36元、5元5角、12元、3元5角（卷面为带价签玩具图）。选最便宜的两种：3元5角+5元5角=9元。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p016.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '应用', 3, '{"stem": "明明有5元、10元、20元的人民币各5张，他要买下面这只25元的玩具熊，有哪几种付钱方式可以正好付清？", "options": null}', '4种：①5张5元；②3张5元和1张10元；③1张5元和2张10元；④1张5元和1张20元。', '按20元用几张分类：不用20元时，25元可由“5张5元”或“3张5元+1张10元”或“1张5元+2张10元”凑出；用1张20元时还需5元，即“1张5元+1张20元”。共4种，各面值张数均不超过5张。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p016.png"]');
